$globalDefaults=['app_name'=>'PocketCat','app_url'=>'https://pocketcat.online','site_meta_description'=>'PocketCat productivity workspace','growth_base'=>'10000','growth_rates'=>'5,10,15,25,10','growth_chart_title'=>'6-month user growth demo','growth_chart_description'=>'Presentation-only sample starting at 10,000 users with 5%, 10%, 15%, 25% and 10% monthly increases.','growth_demo_badge'=>'1','show_demo_growth_chart'=>'1','logo_url'=>'','theme_mode'=>'light','theme_brand'=>'#2563eb','theme_brand2'=>'#7c3aed','theme_bg'=>'#f6f8fc','theme_card'=>'#ffffff','theme_ink'=>'#122033','theme_muted'=>'#68768a','theme_line'=>'#e5eaf1','theme_high'=>'#b91c1c','theme_medium'=>'#92400e','theme_low'=>'#166534','footer_text'=>'Calm work management for modern teams.','footer_copyright'=>'© '.date('Y').' PocketCat · Based in India','social_x_url'=>'https://x.com/RoyHindinews','social_linkedin_url'=>'','social_github_url'=>'','nav_home_label'=>'Home','nav_product_label'=>'Product','nav_features_label'=>'Features','nav_how_label'=>'How it works','nav_pricing_label'=>'Pricing','nav_about_label'=>'About','nav_contact_label'=>'Contact','label_tasks'=>'Tasks','label_notes'=>'Notes','label_projects'=>'Projects','label_dashboard'=>'Dashboard','label_completed'=>'Completed','label_todo'=>'Todo','label_in_progress'=>'In Progress','label_ai_assistant'=>'AI Assistant','label_search'=>'Search'];
