$globalValue=static function(string $key)use($globalDefaults):string{$value=setting($key,null);return ($value===null||$value==='')?(string)($globalDefaults[$key]??''):(string)$value;};
$activityValue=static function(string $key)use($activityDefaults):string{$value=setting($key,null);return ($value===null||$value==='')?(string)($activityDefaults[$key]??''):(string)$value;};
$validUrl=static function(string $value,bool $allowBlank=true):string{
    $value=trim($value);
    if($allowBlank&&$value==='')return '';
    return (preg_match('~^https?://[^\\s]+$~i',$value)&&filter_var($value,FILTER_VALIDATE_URL))?$value:'';
};
$validGrowthRates=static function(string $value,string $fallback):string{
    $value=trim($value);
    if($value==='')return $fallback;
    $parts=array_map('trim',explode(',',$value));
    if(count($parts)>5)return $fallback;
    foreach($parts as $part){
        if($part===''||!is_numeric($part)||(float)$part<0||(float)$part>100)return $fallback;
    }
    $normalized=[];
    foreach($parts as $part){
        $number=(string)$part;
        if(str_contains($number,'.'))$number=rtrim(rtrim($number,'0'),'.');
        $normalized[]=$number;
    }
    return implode(',',$normalized);
};
$validCounter=static function(string $value,string $fallback):string{
    $value=preg_replace('/[^0-9]/','',trim($value));
    if($value==='')return $fallback;
    return ltrim($value,'0')===''?'0':ltrim($value,'0');
};
