 if($action==='global'){
  $rules=platform_autofill_rules();
  foreach($activityDefaults as $k=>$default){
   if(!array_key_exists($k,$_POST))continue;
   set_setting($k,$validCounter((string)post($k,$default),$default));
   if(isset($rules[$k]))$rules[$k]['last_run']=time();
