 }
 if($action==='theme'){foreach(['theme_brand','theme_brand2','theme_bg','theme_card','theme_ink','theme_muted'] as $k){if(!array_key_exists($k,$_POST))continue;$v=trim((string)post($k,$globalDefaults[$k]??''));if(!preg_match('/^#[0-9A-Fa-f]{6}$/',$v))$v=$globalDefaults[$k]??'#2563eb';set_setting($k,$v);}flash('success','Theme updated live.');redirect('/admin/site-editor/?page='.rawurlencode($slug).'#theme-settings');}
 if($action==='save-page'){ $slug=(string)post('page_slug','home');if(!isset($pages[$slug]))$slug='home';$html=(string)post('html_content','');$title=trim((string)post('page_title',$pages[$slug]));db()->prepare('INSERT INTO site_content(page_slug,title,html_content,updated_at) VALUES(?,?,?,NOW()) ON DUPLICATE KEY UPDATE title=VALUES(title),html_content=VALUES(html_content),updated_at=NOW()')->execute([$slug,$title,$html]);if(post('ajax')==='1')json_response(['ok'=>true,'saved_at'=>date('H:i:s')]);flash('success','Published and live.');redirect('/admin/site-editor/?page='.rawurlencode($slug));}
 if($action==='reset-page'){db()->prepare('DELETE FROM site_content WHERE page_slug=?')->execute([(string)post('page_slug','home')]);flash('success','Page restored to built-in default.');redirect('/admin/site-editor/?page='.rawurlencode($slug));}
 if($action==='save-theme'){
  $urlKeys=['app_url','logo_url','social_x_url','social_linkedin_url','social_github_url'];
  $labelKeys=['nav_home_label','nav_product_label','nav_features_label','nav_how_label','nav_pricing_label','nav_about_label','nav_contact_label','label_tasks','label_notes','label_projects','label_dashboard','label_completed','label_todo','label_in_progress','label_ai_assistant','label_search'];
  foreach($globalDefaults as $k=>$default){
   if(!array_key_exists($k,$_POST))continue;
   $v=trim((string)post($k,$default));
   if($k==='app_name')$v=mb_substr($v,0,120);
   elseif($k==='site_meta_description')$v=mb_substr($v,0,300);
   elseif($k==='growth_base')$v=$validCounter($v,$default);
   elseif($k==='growth_rates')$v=$validGrowthRates($v,$default);
   elseif($k==='growth_chart_title')$v=mb_substr($v,0,160);
   elseif($k==='growth_chart_description')$v=mb_substr($v,0,500);
   elseif($k==='growth_demo_badge')$v='1';
   elseif($k==='show_demo_growth_chart')$v=in_array($v,['0','1'],true)?$v:'1';
   elseif(in_array($k,$urlKeys,true)){
    $validated=$validUrl($v,$k!=='app_url');
    $v=$validated!==''?$validated:($k==='app_url'?$default:'');
   } elseif(in_array($k,$labelKeys,true))$v=mb_substr($v,0,80);
   elseif($k==='footer_text')$v=mb_substr($v,0,300);
   elseif($k==='footer_copyright')$v=mb_substr($v,0,300);
   elseif($k==='theme_mode'&&!in_array($v,['light','dark'],true))$v=$default;
   elseif(str_starts_with($k,'theme_')&&$k!=='theme_mode'&&!preg_match('/^#[0-9A-Fa-f]{6}$/',$v))$v=$default;
   set_setting($k,$v);
  }
  // The chart itself is optional; if its checkbox is unchecked, persist OFF explicitly.
  set_setting('show_demo_growth_chart',in_array('1',(array)($_POST['show_demo_growth_chart']??[]),true)?'1':((string)($_POST['show_demo_growth_chart']??'0')==='1'?'1':'0'));
  // The chart visibility toggle controls whether the illustrative growth chart is shown.
  set_setting('growth_demo_badge','1');
  flash('success','Global settings published instantly.');
  redirect('/admin/site-editor/?page='.rawurlencode($slug).'#global');
 }
 if($action==='reset-theme'){foreach($globalDefaults as $k=>$v)set_setting($k,(string)$v);flash('success','Global customization reset to defaults.');redirect('/admin/site-editor/?page='.rawurlencode($slug));}
}
